package com.doghider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("doghider")
public interface DogHiderConfig extends Config
{
	@ConfigItem(
		keyName = "hideOtherDogs",
		name = "Hide Other Players' Dogs",
		description = "Hide shelter dogs and puppies following other players",
		position = 1
	)
	default boolean hideOtherDogs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideStrayDogs",
		name = "Hide Stray Dogs",
		description = "Hide world stray dogs (Varrock stray dog, Clan Hall dog, Molossus)",
		position = 2
	)
	default boolean hideStrayDogs()
	{
		return false;
	}
}

package com.doghider;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Renderable;
import net.runelite.client.callback.Hooks;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Dog Hider",
	description = "Hides shelter dogs and puppies while preserving cool pets",
	tags = {"npcs", "pets", "dogs", "hide"}
)
public class DogHiderPlugin extends Plugin
{
	// The 12 shelter breeds added in 'A Ruff Situation'
	private static final Set<String> SHELTER_BREEDS = ImmutableSet.of(
		"bernese", "chihuahua", "collie", "corgi", "greyhound",
		"husky", "labrador", "pug", "samoyed", "spaniel",
		"shiba", "yorkie"
	);

	@Inject
	private Client client;

	@Inject
	private DogHiderConfig config;

	@Inject
	private Hooks hooks;

	private final Hooks.RenderableDrawListener drawListener = this::shouldDraw;

	@Provides
	DogHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DogHiderConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		hooks.registerRenderableDrawListener(drawListener);
		log.debug("Dog Hider started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		hooks.unregisterRenderableDrawListener(drawListener);
		log.debug("Dog Hider stopped");
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		if (!(renderable instanceof NPC))
		{
			return true;
		}

		NPC npc = (NPC) renderable;

		// Always show local player's own follower/pet
		if (npc == client.getFollower())
		{
			return true;
		}

		NPCComposition comp = npc.getComposition();
		if (comp == null)
		{
			return true;
		}

		String name = comp.getName();
		if (name == null)
		{
			return true;
		}

		if (isDog(name))
		{
			// Follower of another player
			if (comp.isFollower())
			{
				return !config.hideOtherDogs();
			}

			// Stray / wild world dogs
			if (config.hideStrayDogs())
			{
				return false;
			}
		}

		return true;
	}

	private boolean isDog(String npcName)
	{
		String lower = npcName.toLowerCase();

		// Check the 12 shelter dog breeds
		for (String breed : SHELTER_BREEDS)
		{
			if (lower.contains(breed))
			{
				return true;
			}
		}

		// Stray dogs (Varrock "Stray dog", Clan Hall "Dog", Varlamore "Molossus")
		if (config.hideStrayDogs() && (lower.contains("stray dog") || lower.equals("dog") || lower.contains("molossus")))
		{
			return true;
		}

		return false;
	}
}

package com.doghider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DogHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DogHiderPlugin.class);
		RuneLite.main(args);
	}
}
